import numpy as np, time
def pi_sieve(x):
    s = np.ones(x+1, dtype=bool); s[:2]=False
    for i in range(2, int(x**0.5)+1):
        if s[i]: s[i*i::i]=False
    return int(s.sum())
for n in (24,25,26):
    x=(1<<n)-1; t=time.perf_counter(); p=pi_sieve(x)
    print(f'pi(2^{n}-1) = pi({x}) = {p}   ({time.perf_counter()-t:.1f}s)')
# also the exact powers of two for literature cross-check
for n in (25,26):
    X=(1<<n); 
    print(f'pi(2^{n}) = pi({X}) = {pi_sieve(X)}  (known: 2063689 @25, 3957809 @26)')
